    gNextCarryable = 0; a.PerformAction();
    if (gCreated != 2 || car.count != 1) fails |= 4;
    a.ItemDefIndex = 0; a.PerformAction();
    a.ItemDefIndex = 42; c.carrying = 0; a.PerformAction();
