struct Unsheathe { Thing* creature; char anim[48]; Thing* item; long a, b; void* follow;
    Unsheathe(Thing& c, const Str& n, Thing& i, long x, long y, void* f) : creature(&c), item(&i), a(x), b(y), follow(f) { std::strcpy(anim, n.s); } };
